{
	"blocks": [
    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": "${tenant}: Pipeline Monitoring Policy Execution details for *${incidentMetadata.pipelineName}*"
      }
    },
    {
      "type": "divider"
    },
    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": "*Info : *"
      }
    },
    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": "*Pipeline Name:* ${incidentMetadata.pipelineName}"
      }
    },
    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": "*Monitoring Policy Name:* ${incidentMetadata.policyName}"
      }
    },
    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": "*${incidentMetadata.backingEntityType} Name:* ${incidentMetadata.backingEntityUid}"
      }
    },
    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": "*Metric Name:* ${incidentMetadata.baseMetric}"
      }
    },
    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": "*Metric Measurement:* ${incidentMetadata.measurementType}"
      }
    },
    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": "*Result Summary:* ${resultSummary}"
      }
    },
    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": "To Check the Execution Details"
      }
    },
    {
      "type": "actions",
      "elements": [
        {
          "type": "button",
          "text": {
            "type": "plain_text",
            "text": "Click Here",
            "emoji": true
          },
          "value": "click_me_123",
          "url": "${link}"
        }
      ]
    },
    {
      "type": "divider"
    }
  ]
}
